-- ==============================================================================
-- Nordible Directory: Clean Slate Setup (Auto-Generated UUIDs)
-- ==============================================================================

-- 1. Clean slate: drop any old tables
DROP TABLE IF EXISTS businesses CASCADE;
DROP TABLE IF EXISTS categories CASCADE;
DROP TABLE IF EXISTS users CASCADE;
DROP TABLE IF EXISTS tenants CASCADE;

CREATE EXTENSION IF NOT EXISTS "pgcrypto";

-- 2. Tenants Table
CREATE TABLE tenants (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    slug VARCHAR(64) UNIQUE NOT NULL,
    name VARCHAR(255) NOT NULL,
    tagline_de TEXT,
    tagline_en TEXT NOT NULL,
    primary_color VARCHAR(9) NOT NULL DEFAULT '#145BFF',
    accent_color VARCHAR(9) NOT NULL DEFAULT '#FF9F1A',
    logo_text VARCHAR(64) NOT NULL,
    custom_domain VARCHAR(255) UNIQUE,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- 3. Categories Table
CREATE TABLE categories (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    slug VARCHAR(64) NOT NULL,
    name_de VARCHAR(128),
    name_en VARCHAR(128) NOT NULL,
    icon VARCHAR(64) NOT NULL DEFAULT 'Grid',
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    CONSTRAINT uq_tenant_category_slug UNIQUE (tenant_id, slug)
);

-- 4. Businesses Table (Auto-generated UUID, no manual IDs)
CREATE TABLE businesses (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    category_id UUID NOT NULL REFERENCES categories(id) ON DELETE RESTRICT,
    slug VARCHAR(128) UNIQUE NOT NULL,
    name VARCHAR(255) NOT NULL,
    description_de TEXT,
    description_en TEXT,
    address VARCHAR(255) NOT NULL,
    city VARCHAR(128) NOT NULL,
    phone VARCHAR(64),
    website VARCHAR(512),
    logo_url TEXT,
    rating NUMERIC(3, 2) NOT NULL DEFAULT 5.0,
    review_count INTEGER NOT NULL DEFAULT 0,
    is_verified BOOLEAN NOT NULL DEFAULT FALSE,
    is_open_now BOOLEAN NOT NULL DEFAULT TRUE,
    hours VARCHAR(255),
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- 5. Enable Row-Level Security (Public Read)
ALTER TABLE tenants ENABLE ROW LEVEL SECURITY;
ALTER TABLE categories ENABLE ROW LEVEL SECURITY;
ALTER TABLE businesses ENABLE ROW LEVEL SECURITY;

CREATE POLICY "Public tenants read" ON tenants FOR SELECT USING (true);
CREATE POLICY "Public categories read" ON categories FOR SELECT USING (true);
CREATE POLICY "Public businesses read" ON businesses FOR SELECT USING (true);

